'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{execFileSync}=require('node:child_process'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const repo=path.resolve(__dirname,'../..'),root=process.env.TITRES_CREATION_ASSET_DIR||repo,read=f=>fs.readFileSync(path.join(root,f),'utf8'),base='fb25f0ec4608e7fda14d36ba1edcfbd235dc5ce9';
const selected=(s,names)=>parse(s).body.filter(n=>n.type==='FunctionDeclaration'&&names.includes(n.id.name)).map(n=>s.slice(n.start,n.end)).join('\n'),baseline=execFileSync('git',['show',base+':creation.js'],{cwd:repo,encoding:'utf8',maxBuffer:4e6}),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
async function setup(page,before){await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body><input id="draft" value="Brouillon à conserver"><div id="s8" class="screen active"><button class="nbtn nnext" data-i18n="creation.nav.validate">Valider et entrer dans le jeu</button></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});for(const f of ['i18n/resources.js','i18n/connection-resources.js'])await page.addScriptTag({content:read(f)});await page.evaluate(async()=>{await i18next.init({lng:'fr',fallbackLng:'fr',resources:RP_I18N_RESOURCES,interpolation:{escapeValue:false}});window.RP_I18N_LANGUES_SUPPORTEES=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];window.calls=[];window.playerState={pa:17,arg:3000,inventory:[{id:'fixture'}],progression:{stage:3}};window.cache={};Object.defineProperty(window,'localStorage',{value:{setItem:(k,v)=>{cache[k]=v;},removeItem:k=>{delete cache[k];}}});window.G={country:'republic',city:'ville_b',origin:'fixture',school:'fixture',archetype:'fixture',career:'fixture',freeStats:{},freePts:2,name:'PJ Fixture',bio:'Récit libre conservé',motto:'Devise libre'};window.STAT_DEFS=[];window.totalArg=()=>1000;window.resources=()=>({inf:25,pop:30,dis:85});window.genreValeur=()=>null;window.getBase=()=>0;window.rpMarquerProprietaireCache=()=>calls.push(['cache-owner']);window.goTo=n=>calls.push(['screen',n]);window.sbSavePersonnage=()=>{throw Error('Ancienne sauvegarde appelée');};window.sbRpc=async name=>{calls.push(['rpc',name]);return window.mode==='otherOwned'?'Autre Personnage':window.mode==='concurrentOwn'?'PJ Fixture':null;};window.sbCreerCompteBancaire=async o=>calls.push(['bank',o]);window.sbEnregistrerNaissance=async(...a)=>calls.push(['birth',...a]);window.sbCreerPersonnageInitial=async o=>{calls.push(['create',o]);await new Promise(r=>window.resolveCreation=r);if(window.mode==='throw')throw Error('fixture');return window.mode==='success'?{ok:true}:{ok:false,raison:window.mode==='otherOwned'||window.mode==='concurrentOwn'?'erreur_reseau':window.mode};};const NativeDate=Date;window.Date=class extends NativeDate{constructor(...a){super(...(a.length?a:['2026-11-14T00:00:00.000Z']));}static now(){return 1794614400000;}};window.businessSnapshot=()=>JSON.stringify({calls,cache,G,playerState,lock:window.creationLocked?.()});window.uiSnapshot=()=>JSON.stringify({draft:document.getElementById('draft').value,focus:document.activeElement.id,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,scroll:[scrollX,scrollY]});});await page.addScriptTag({content:selected(read('i18n/i18n-init.js'),['appliquerTraductionsRP'])});await page.addScriptTag({content:'let CREATION_EN_COURS=false;\n'+selected(before?baseline:read('creation.js'),['validateChar'])+'\nwindow.creationLocked=()=>CREATION_EN_COURS;'});}
async function begin(page,mode,custom=false){return page.evaluate(({mode,custom})=>{window.mode=mode;calls.length=0;cache={};document.getElementById('creation-erreur')?.remove();const b=document.querySelector('#s8 .nnext');b.disabled=false;if(custom){b.removeAttribute('data-i18n');b.textContent='Libellé libre';}else{b.setAttribute('data-i18n','creation.nav.validate');appliquerTraductionsRP();}document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,5);window.pendingCreation=validateChar();return {business:businessSnapshot(),ui:uiSnapshot(),button:b.textContent,disabled:b.disabled};},{mode,custom});}
async function finish(page){return page.evaluate(async()=>{resolveCreation();await pendingCreation;const zone=document.getElementById('creation-erreur'),b=document.querySelector('#s8 .nnext');return {business:businessSnapshot(),html:zone?.innerHTML||null,body:zone?Array.from(zone.childNodes).slice(1).map(n=>n.outerHTML||n.textContent).join(''):null,button:b.textContent,disabled:b.disabled};});}
test('création : neuf langues, 320/390/1280, attente et six refus, français et appels identiques à main, aucune répétition ni saisie perdue',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;
 try{for(const width of [320,390,1280]){const current=await browser.newPage({viewport:{width,height:900}}),before=await browser.newPage({viewport:{width,height:900}}),errors=[],requests=[];current.on('request',r=>requests.push(r.url()));current.on('pageerror',e=>errors.push(String(e)));await setup(current,false);await setup(before,true);
 for(const mode of ['nom_deja_pris','compte_a_deja_un_personnage','genre_requis','session_perimee','raison_libre','otherOwned','throw','success','concurrentOwn']){
  for(const p of [current,before])await p.evaluate(async()=>{await i18next.changeLanguage('fr');appliquerTraductionsRP();});const a=await begin(current,mode),b=await begin(before,mode);assert.deepEqual(a,b,mode+' attente français et appels identiques');assert.equal(a.disabled,true);
  const pendingSnapshot=a.business,pendingUi=a.ui;for(const lang of langs){await current.evaluate(async lang=>{await i18next.changeLanguage(lang);appliquerTraductionsRP();},lang);assert.equal(await current.evaluate(()=>businessSnapshot()),pendingSnapshot);assert.equal(await current.evaluate(()=>uiSnapshot()),pendingUi);assert.equal(await current.locator('#s8 .nnext').textContent(),await current.evaluate(()=>i18next.t('connectionUi.characterCreationWorking')));assert.equal(await current.locator('#s8 .nnext').isDisabled(),true);assert.equal(await current.locator('#s8 .nnext').getAttribute('dir'),lang==='ar'?'rtl':null);assert.equal(await current.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);switches++;}
  await current.evaluate(()=>validateChar());assert.equal(await current.evaluate(()=>calls.filter(c=>c[0]==='create').length),1,'double appel ignoré pendant attente');
  await current.evaluate(async()=>{await i18next.changeLanguage('fr');appliquerTraductionsRP();});const done=await finish(current),old=await finish(before);assert.equal(done.business,old.business,mode+' mêmes appels/cache/verrou');assert.equal(done.body,old.body,mode+' explication entière inchangée');assert.equal(done.button,old.button);assert.equal(done.disabled,old.disabled);
  if(old.html){assert.equal(done.html.replace(/ data-i18n="[^"]*"/g,'').replace(/ data-i18n-fallback="[^"]*"/g,''),old.html,'français et structure identiques');const business=done.business,ui=await current.evaluate(()=>uiSnapshot());for(const lang of langs){await current.evaluate(async lang=>{await i18next.changeLanguage(lang);appliquerTraductionsRP();},lang);const title=current.locator('#creation-erreur strong'),key=await title.getAttribute('data-i18n');assert.ok(key);assert.equal(await title.getAttribute('dir'),lang==='ar'?'rtl':null);assert.equal(await title.textContent(),await current.evaluate(key=>i18next.t(key),key));assert.equal(await current.evaluate(()=>businessSnapshot()),business);assert.equal(await current.evaluate(()=>uiSnapshot()),ui);assert.equal(await current.evaluate(()=>document.getElementById('creation-erreur').scrollWidth>document.getElementById('creation-erreur').clientWidth),false);assert.equal(await current.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await current.locator('#s8 .nnext').textContent(),await current.evaluate(()=>i18next.t('creation.nav.validate')));switches++;}}
  else if(await current.evaluate(()=>creationLocked()))await current.evaluate(()=>{CREATION_EN_COURS=false;});
  if(await before.evaluate(()=>creationLocked()))await before.evaluate(()=>{CREATION_EN_COURS=false;});
 }
 // La réponse arrivée dans une autre langue restaure le libellé courant, jamais l'ancien français.
 await current.evaluate(async()=>{await i18next.changeLanguage('fr');appliquerTraductionsRP();});await begin(current,'genre_requis');await current.evaluate(async()=>{await i18next.changeLanguage('de');appliquerTraductionsRP();});await finish(current);assert.equal(await current.locator('#s8 .nnext').textContent(),await current.evaluate(()=>i18next.t('creation.nav.validate')));
 await begin(current,'genre_requis',true);await current.evaluate(async()=>{await i18next.changeLanguage('ar');appliquerTraductionsRP();});await finish(current);assert.equal(await current.locator('#s8 .nnext').textContent(),'Libellé libre');assert.equal(await current.locator('#s8 .nnext').getAttribute('data-i18n'),null);
 await current.evaluate(async()=>{i18next.removeResourceBundle('de','translation');await i18next.changeLanguage('de');appliquerTraductionsRP();});await begin(current,'genre_requis');assert.equal(await current.locator('#s8 .nnext').textContent(),'Creation en cours...');await finish(current);assert.equal(await current.locator('#creation-erreur strong').textContent(),'Genre manquant');assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await current.close();await before.close();}
 assert.equal(switches,432);console.log('432 bascules : création simulée unique, progression/cache/PA/appels conservés ; aucun compte réel.');
 }finally{await browser.close();}
});
